/// <summary>
///    Finds the specified record in the <c>AVAPriceSurchargeValues</c> table.
/// </summary>
/// <param name="_code">
///    The record ID of the <c>AVAPriceSurchargeValues</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceSurchargeValues</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceSurchargeValues find( AVAPriceSurchargeCode   _code,
                                            boolean                 _forUpdate = false)
{
    AVAPriceSurchargeValues record;
    Date                    dateToday;


    dateToday =  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    record.selectForUpdate(_forUpdate);

    if(_code)
    {
        select firstonly record
        where   record.AVAPriceSurchargeCode == _code
            &&  (   (record.ValidFromDate    <= dateToday   &&  record.ValidToDate  >= dateToday    )
                ||  (record.ValidFromDate    <= dateToday   &&  record.ValidToDate  == dateNull()   )
                ||  (record.ValidFromDate    == dateNull()  &&  record.ValidToDate  >= dateToday    )   );
    }

    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceSurchargeValues</c> table.
/// </summary>
/// <param name="_code">
///    The record ID of the <c>AVAPriceSurchargeValues</c> record to find.
/// </param>
/// <param name="_date">
///     <c>Date</c> as type
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceSurchargeValues</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceSurchargeValues findAtDate(   AVAPriceSurchargeCode   _code,
                                                    Date                    _date       = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                                    boolean                 _forUpdate  = false                                                             )
{
    AVAPriceSurchargeValues record;
    Date                    locDate;

    locDate = _date;

    if(locDate == dateNull())
    {
        locDate =  DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    }

    record.selectForUpdate(_forUpdate);

    if(_code)
    {
        select firstonly record
        where   record.AVAPriceSurchargeCode == _code
            &&  (   (record.ValidFromDate    <= locDate     &&  record.ValidToDate  >= locDate      )
                ||  (record.ValidFromDate    <= locDate     &&  record.ValidToDate  == dateNull()   )
                ||  (record.ValidFromDate    == dateNull()  &&  record.ValidToDate  >= locDate      )   );
    }

    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceSurchargeTable</c> table.
/// </summary>
/// <param name="_code">
///    The record ID of the <c>AVAPriceSurchargeTable</c> record to find.
/// </param>
/// <returns>
///    true if record in the <c>AVAPriceSurchargeTable</c> table exists
/// </returns>
public static boolean exist(AVAPriceSurchargeCode _code)
{
    return      _code
            &&  (   select firstonly AVAPriceSurchargeTable
                    index hint AVAPriceSurchargeTableIdx
                    where AVAPriceSurchargeTable.AVAPriceSurchargeCode == _code).Recid != 0;
}

/// <summary>
///    AVA <c>displayAVAPriceSurchargeLanguage</c> method.
/// </summary>
/// <param name="_languageId">
///    <c>LanguageId</c> as type
/// </param>
/// <returns>
///    <c>Description</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Description displayAVAPriceSurchargeLanguage(LanguageId _languageId = CompanyInfo::languageId())
{
    Description retVal;

    retVal = AVAPriceSurchargeTranslation::findByAVAPriceSurchargeAndLanguage(this.RecId, _languageId).Description;

    if(!retVal)
    {
        retVal = AVAPriceSurchargeTable::find(this.AVAPriceSurchargeCode).Description;
    }
    if(!retVal)
    {
        retVal = this.AVAPriceSurchargeCode;
    }

    return retVal;
}
